pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1e24);

        // Adversarial counterparty: the configured LogFile whose AddMessage always reverts.
        Reverter logAddr = new Reverter();
        c.SetLogFile(address(logAddr));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put(0) { ok = true; } catch { ok = false; }

        // Reference: Put always reverts because the log call to the reverting logger fails.
        // Mutant: LogFile is address(0), the log call silently targets empty storage and Put succeeds.
        assertTrue(!ok);
    }
}

contract Reverter {
    function AddMessage(address, uint256, string calldata) external pure { revert(); }
    fallback() external payable { revert(); }
}

