pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);

        // adversarial logger: rejects every AddMessage (all external log writes fail)
        RejectingLogger logger = new RejectingLogger();

        // configure the logger before initialization locks it in
        c.SetLogFile(address(logger));
        c.Initialized();

        // attempt a deposit; in the reference C the mandatory log write reverts,
        // so the whole Put reverts and no ether can ever be retained by c
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Put{value: amount}(lockTime) {
            // put "succeeded"
        } catch {
            // put reverted
        }

        // Rule: with a rejecting logger, a deposit can never complete, so c must hold zero ether.
        assertTrue(address(c).balance == 0, "deposit completed despite rejecting logger");
    }
}

contract RejectingLogger {
    fallback() external payable {
        revert();
    }
}

