pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller actor;

    function setUp() public {
        c = new C();
        actor = new Caller();
        actor.setTarget(c);
    }

    function testFuzz_property(uint256 lockTime, address logAddr) public {
        vm.assume(logAddr.code.length == 0); // admissible log: plain address with no code
        // The caller is a contract. In the reference, LogFile = logAddr (codeless), so the
        // LogFile.AddMessage low-level call inside Put succeeds silently and Put succeeds.
        // In the mutant, LogFile = msg.sender (the Caller contract, which has code but no
        // AddMessage/fallback), so AddMessage reverts and Put must revert too.
        bool ok;
        try actor.go(lockTime, logAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Caller {
    C c;

    function setTarget(C _c) external {
        c = _c;
    }

    function go(uint256 lockTime, address logAddr) external {
        c.SetLogFile(logAddr);
        c.Put(lockTime);
    }
}

