pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address logAddr) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(logAddr != address(c) && logAddr != address(this));
        vm.deal(address(this), amount);
        // configure the log file to the fuzzed address (done by this contract itself)
        (bool s0,) = address(c).call(abi.encodeWithSignature("SetLogFile(address)", logAddr));
        assertTrue(s0);
        // a Put by this contract must succeed: LogFile.AddMessage targets the configured address
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        assertTrue(ok);
    }
}
// no adversarial helper needed: the fuzzed logAddr is an EOA (codeless), so the reference's
// LogFile.AddMessage low-level call always succeeds, while the mutant stores this test contract
// (which has no AddMessage) and every Put reverts.

